const result = {};
for (const key in form) {
    if (form.hasOwnProperty(key)) {
        const titleCaseKey = key.charAt(0).toUpperCase() + key.slice(1);

        if (form[key] === "") continue;

        if (/^(is|need|with|active)/i.test(key) && method === "POST") {
            result[titleCaseKey] = form[key] || false;
        } else {
            result[titleCaseKey] = form[key];
        }
    }
}
return result;

$ctrl.uiState.isInserting = true;

switch ($ctrl.uiState.currentTab.name) {
    case "pay_schedule":
        $ctrl.payrollAppApi.lonti_app_payroll_service_pay_schedule_InsertPaySchedule({},
            {
                "DisplayName": $ctrl.form4.displayName,
                "Description": $ctrl.form4.description,
                "Active": $ctrl.form4.active ?? false,
                "Frequency": $ctrl.form4.frequency,
                "DayStartTime": $ctrl.utils.extractTimeFromDate($ctrl.form4.dayStartTime),
                "MonthFirstStartDay": $ctrl.form4.monthFirstStartDay,
                "MonthSecondStartDay": $ctrl.form4.monthSecondStartDay,
                "MonthFirstPayDay": $ctrl.form4.monthFirstPayDay,
                "MonthSecondPayDay": $ctrl.form4.monthSecondPayDay,
                "MaxImbalance": $ctrl.form4.maxImbalance,
                "WeekStartDayName": $ctrl.form4.weekStartDayName,
                "WeekPayDayName": $ctrl.form4.weekPayDayName,
                "WorkingDays": $ctrl.convertWorkingDaysToString($ctrl.form4.workingDays),
                "PayDateOnBD": $ctrl.form4.payDateOnBd,
                "EffectiveFromDate": $ctrl.utils.parseDate($ctrl.form4.effectiveFromDate),
                "EffectiveToDate": $ctrl.form4.effectiveToDate ? $ctrl.utils.parseDate($ctrl.form4.effectiveToDate) : undefined,
                "PaidInArrears": $ctrl.form4.paidInArrears ?? false,
                "CurrencyId" : $ctrl.form4.currencyId,
                "CompanyId": $ctrl.globalSelectedCompany.companyId
            }, {
            headers: $ctrl.authCookies.setHeaders()
        }).then(result => {
            $ctrl.utils.toast(`Successfully added ${$ctrl.form4.displayName}`, result.data.result);
            $ctrl.handlers.onAddInit();

            $ctrl.uiState.stored = {
                tabId: $ctrl.uiState.currentTab.id,
                entityId: result.data.payschedule.Id
            }

            $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
            $ctrl.utils.resetForm($ctrl.form4);
        }).catch(reason => {
            $ctrl.utils.toast(reason.data.message, reason.data.result);
        }).finally(() => $ctrl.uiState.isInserting = false);
        break;

    case "position":
        $ctrl.payrollAppApi.lonti_app_payroll_service_position_InsertPosition({},
            {
                "Department": $ctrl.form5.department,
                "Title": $ctrl.form5.title,
                "EffectiveFromDate": $ctrl.utils.parseDate($ctrl.form5.effectiveFromDate),
                "EffectiveToDate": $ctrl.form5.effectiveToDate ? $ctrl.utils.parseDate($ctrl.form5.effectiveToDate) : undefined,
                "Active": $ctrl.form5.active ?? false,
                "Description": $ctrl.form5.description,
                "Salaried": ($ctrl.form5.salaried !== undefined) ? $ctrl.form5.salaried : false,
                "WeeklyDays": $ctrl.form5.weeklyDays,
                "WeeklyHours": $ctrl.form5.weeklyHours,
                "BaseRateUnit": $ctrl.form5.baseRateUnit,
                "AnnualRate": $ctrl.form5.annualRate,
                "CurrencyId": $ctrl.form5.currencyId,
                "PayScheduleId": $ctrl.form5.payScheduleId,
                "CompanyId": $ctrl.globalSelectedCompany.companyId
            }, {
            headers: $ctrl.authCookies.setHeaders()
        }).then(result => {
            $ctrl.utils.toast(`Successfully added ${$ctrl.form5.title}`, result.data.result);
            $ctrl.handlers.onAddInit();
            $ctrl.utils.resetForm($ctrl.form5);

            $ctrl.uiState.stored = {
                tabId: $ctrl.uiState.currentTab.id,
                entityId: result.data.position.Id
            }

            $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
        }).catch(reason => {
            $ctrl.utils.toast(reason.data.message, reason.data.result);
        }).finally(() => $ctrl.uiState.isInserting = false);
        break;
}

$ctrl.uiState.isUpdating = true;
const entityId = $ctrl.uiState.selectedEntity?.Id;

// Keep form open with updated info and reselect table row
async function updateEditForm() {
    // Assign updated fields function
    function buildUpdatePayload(formObj, existingEntity) {
        const pascalCased = Object.fromEntries(
            Object.entries(formObj)
                .filter(([key, value]) => value != null && !["effectiveFromDate", "effectiveToDate", "workingDays", "dayStartTime", "payDateOnBd"].includes(key))
                .map(([key, value]) => [$ctrl.utils.toPascalKey(key), value])
        );

        const fromDateChanged = formObj.effectiveFromDate && formObj.effectiveFromDate !== existingEntity.EffectiveFromDate;
        const toDateChanged = formObj.effectiveToDate && (fromDateChanged || formObj.effectiveToDate !== existingEntity.EffectiveToDate);

        if (fromDateChanged) {
            pascalCased.EffectiveFromDate = $ctrl.utils.parseDate(formObj.effectiveFromDate);
        }

        if (toDateChanged) {
            pascalCased.EffectiveToDate = $ctrl.utils.parseDate(formObj.effectiveToDate);
        }

        if (formObj.workingDays && Object.values(formObj.workingDays).filter(Boolean).length > 0) {
            pascalCased.WorkingDays = $ctrl.convertWorkingDaysToString(formObj.workingDays);
        }

        if (formObj.dayStartTime) {
            pascalCased.DayStartTime = typeof formObj.dayStartTime === "object"
                ? $ctrl.utils.extractTimeFromDate(formObj.dayStartTime)
                : formObj.dayStartTime;
        }

        if (formObj.payDateOnBd) {
            pascalCased.PayDateOnBD = formObj.payDateOnBd;
        }

        return Object.assign({}, existingEntity, pascalCased);
    }

    const tableRowIndex = $ctrl.tabStore[$ctrl.uiState.currentTab.name].data.findIndex(entity => entity.Id === entityId);
    if (tableRowIndex === -1) {
        throw new Error(`Entity not found in table`);
    }

    $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = buildUpdatePayload($ctrl[$ctrl.tabConfig[$ctrl.uiState.currentTab.name].form], $ctrl.uiState.selectedEntity);

    // Hydrate fields based on updated Ids on dropdown selection
    const hydratedEntity = await $ctrl.referenceDataService.hydrateEntity(
        $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex]
    );
    $ctrl.tabStore[$ctrl.uiState.currentTab.name].data[tableRowIndex] = $ctrl.uiState.selectedEntity = hydratedEntity
    $ctrl.$timeout(() => {
        $ctrl.utils.setSelectedBelliniTableRow(tableRowIndex);
    });
    $ctrl.handlers.onEditInit();
    const formToReset = document.querySelector('.form');
    if(formToReset) {
        formToReset.scrollTop = 0;
    }
}

switch ($ctrl.uiState.currentTab.name) {
    case "pay_schedule":
        $ctrl.payrollAppApi.lonti_app_payroll_service_pay_schedule_UpdatePaySchedule({},
            {
                "Id": $ctrl.uiState.selectedEntity.Id,
                "DisplayName": $ctrl.form4.displayName,
                "Description": $ctrl.form4.description,
                "Active": $ctrl.form4.active,
                "Frequency": $ctrl.form4.frequency,
                "DayStartTime": typeof $ctrl.form4.dayStartTime === "object" ? $ctrl.utils.extractTimeFromDate($ctrl.form4.dayStartTime) : $ctrl.form4.dayStartTime,
                "MonthFirstStartDay": $ctrl.form4.monthFirstStartDay,
                "MonthSecondStartDay": $ctrl.form4.monthSecondStartDay,
                "MonthFirstPayDay": $ctrl.form4.monthFirstPayDay,
                "MonthSecondPayDay": $ctrl.form4.monthSecondPayDay,
                "WeekStartDayName": $ctrl.form4.weekStartDayName,
                "WeekPayDayName": $ctrl.form4.weekPayDayName,
                "WorkingDays": ($ctrl.form4.workingDays && (Object.values($ctrl.form4.workingDays).filter(Boolean).length > 0)) ? $ctrl.convertWorkingDaysToString($ctrl.form4.workingDays) : undefined,
                "PaidInArrears": $ctrl.form4.paidInArrears,
                "PayDateOnBD": $ctrl.form4.payDateOnBd,
                "EffectiveFromDate": $ctrl.form4.effectiveFromDate
                    ? $ctrl.form4.effectiveFromDate !== $ctrl.uiState.selectedEntity.EffectiveFromDate
                        ? $ctrl.utils.parseDate($ctrl.form4.effectiveFromDate)
                        : undefined
                    : undefined,
                "EffectiveToDate": $ctrl.form4.effectiveToDate
                    ? ($ctrl.form4.effectiveFromDate !== $ctrl.uiState.selectedEntity.EffectiveFromDate || $ctrl.form4.effectiveToDate !== $ctrl.uiState.selectedEntity.EffectiveToDate)
                        ? $ctrl.utils.parseDate($ctrl.form4.effectiveToDate)
                        : undefined
                    : undefined,
                "CurrencyId": $ctrl.form4.currencyId,
            }, {
            headers: $ctrl.authCookies.setHeaders()
        }).then(async result => {
            $ctrl.utils.toast(`Successfully edited ${$ctrl.selectedEntityName}`, result.data.result);
            try {
                await updateEditForm();
            } catch (uiError) {
                console.error('Failed to refresh form/table after successful update', uiError);
                $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
            }
        }).catch(reason => {
            $ctrl.utils.toast(reason?.data?.message ?? "Update failed.", reason?.data?.result ?? "ERROR");
        }).finally(() => {
            $ctrl.uiState.isUpdating = false;
        });
        break;

    case "position":
        $ctrl.payrollAppApi.lonti_app_payroll_service_position_UpdatePosition({}, {
            "Id": $ctrl.uiState.selectedEntity.Id,
            "Department": $ctrl.form5.department,
            "Title": $ctrl.form5.title,
            "EffectiveFromDate": $ctrl.form5.effectiveFromDate
                ? ($ctrl.form5.effectiveFromDate !== $ctrl.uiState.selectedEntity.EffectiveFromDate)
                    ? $ctrl.utils.parseDate($ctrl.form5.effectiveFromDate)
                    : undefined
                : undefined,
            "EffectiveToDate": $ctrl.form5.effectiveToDate
                ? ($ctrl.form5.effectiveFromDate !== $ctrl.uiState.selectedEntity.EffectiveFromDate) || ($ctrl.form5.effectiveToDate !== $ctrl.uiState.selectedEntity.EffectiveToDate)
                    ? $ctrl.utils.parseDate($ctrl.form5.effectiveToDate)
                    : undefined
                : undefined,
            "Active": $ctrl.form5.active,
            "Description": $ctrl.form5.description,
            "Salaried": $ctrl.form5.salaried,
            "WeeklyDays": $ctrl.form5.weeklyDays,
            "WeeklyHours": $ctrl.form5.weeklyHours,
            "BaseRateUnit": $ctrl.form5.baseRateUnit,
            "AnnualRate": $ctrl.form5.annualRate,
            "PayScheduleId": $ctrl.form5.payScheduleId,
            "CurrencyId": $ctrl.form5.currencyId,
        }, {
            headers: $ctrl.authCookies.setHeaders()
        }).then(async result => {
            $ctrl.utils.toast(`Successfully edited ${$ctrl.selectedEntityName}`, result.data.result);
            try {
                await updateEditForm();
            } catch (uiError) {
                console.error('Failed to refresh form/table after successful update', uiError);
                $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
            }
        }).catch(reason => {
            $ctrl.utils.toast(reason?.data?.message ?? "Update failed.", reason?.data?.result ?? "ERROR");
        }).finally(() => {
            $ctrl.uiState.isUpdating = false;
        });
        break;
}

const toBeDeletedEntity = $ctrl.uiState.selectedEntityName;
const toBeDeletedEntityDetails = $ctrl.utils.legacyGenerateEntityDetails({
    entity: $ctrl.uiState.selectedEntity,
    utils: $ctrl.utils
});

let isConfirmed;
