await $ctrl.$modal.open("delete-entity-modal", {
    props:
    {
        EntityName: toBeDeletedEntity,
        EntityDetails: toBeDeletedEntityDetails
    }
}).then(response => isConfirmed = response.result === "ok");

if (isConfirmed) {
    switch ($ctrl.uiState.currentTab.name) {
        case "pay_schedule":
            $ctrl.payrollAppApi.lonti_app_payroll_service_pay_schedule_DeletePaySchedule({
                id: $ctrl.uiState.selectedEntity.Id
            }, {
                headers: $ctrl.authCookies.setHeaders()
            }).then(result => {
                $ctrl.loaders.loadActiveTab({ isAfterWrite: true });
                $ctrl.utils.toast(`Successfully deleted ${toBeDeletedEntity}`, result.data.result);
                $ctrl.uiState.isDeleting = false;
            }).catch(reason => {
                $ctrl.utils.toast(reason.data.message, reason.data.result);
                $ctrl.uiState.isDeleting = false;
            });
