if (!params) params = {};

const currentTabName = $ctrl.uiState.currentTab.name;

// Default values
const {
    entityType = currentTabName,
    page = $ctrl.tabStore[currentTabName].currentPage,
    query = $ctrl.uiState.currentFilter.currentFilterString,
    isAfterWrite = false
} = params;

const apiQuery = $ctrl.filterService.buildCombinedQuery({
    // quickSearchConfig: $ctrl.tabConfig[entityType].quickSearchDefaultConfig,
    // quickSearchValue: query,
    advancedFilters: $ctrl.uiState.currentFilter.advancedFilters
});

const apiQueryWithCompanyFilter = apiQuery + `&CompanyId=${$ctrl.globalSelectedCompany.companyId}`;

await $ctrl.baseGridControllerService.loadGridData($ctrl, {
    entityType,
    customEntityKey: $ctrl.tabConfig[entityType]?.customEntityKey,
    columnDefs: $ctrl.tabConfig[entityType].columnDefaultConfig,
    page,
    limit: $ctrl.tabStore[entityType].limit,
    query: apiQueryWithCompanyFilter
});

$ctrl.loaders.processOnAddAssignments();
$ctrl.loaders.loadReferenceMaps({ isAfterWrite });

try {
    if (!params) params = {};

    const { isAfterWrite } = params;

    if (isAfterWrite) {
        $ctrl.referenceDataService.clearCache();
    }

    // Fetch formatted options directly from service
    const companyOpts = await $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Company");

    // Update Global Menu
    if ($ctrl.globalSelectedCompany) {
        $ctrl.globalSelectedCompany.companyMap = companyOpts;
        $ctrl.globalSelectedCompany.setMenuItems();
    }

    const [currencyOpts, countryOpts, stateOpts, payScheduleOpts] = await Promise.all([
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Currency"),
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("Country"),
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("State"),
        $ctrl.referenceDataService.dropdownOptionsGetters.getOptions("PaySchedule")
    ]);

    $ctrl.companyMap = companyOpts;
    $ctrl.currencyMap = currencyOpts;
    $ctrl.countryMap = countryOpts;
    $ctrl.payScheduleMap = payScheduleOpts;

    // Group States (This specific logic can stay here or move to a specific StateService)
    $ctrl.stateMap = stateOpts.reduce((acc, state) => {
        if (!acc[state.CountryId]) acc[state.CountryId] = [];
        acc[state.CountryId].push(state);
        return acc;
    }, {});

} catch (e) {
    console.warn("Background reference load failed", e);
}

if (!$ctrl.uiState.stored.entityId) return;

const resetState = (state) => {
    state.original = [];
    state.current = [];
    state.displayed = [];
};

if ($ctrl.uiState.currentTab.name === "pay_schedule") {
    const state = $ctrl.uiState.assignments.pay_schedule.position;
    if (state.willAssignAfterAdd) {
        state.willAssignAfterAdd = false;
        resetState(state);
        return $ctrl.handlers.pay_schedule.position.openPositionAssignment($ctrl.uiState.stored.entityId);
    }
    return;
} else if ($ctrl.uiState.currentTab.name === "position") {
    const posAssignments = $ctrl.uiState.assignments.position;
    const keys = Object.keys(posAssignments)
    const modalQueue = [];

    for (const k of keys) {
        if (posAssignments[k]?.willAssignAfterAdd) {
            posAssignments[k].willAssignAfterAdd = false;
            resetState(posAssignments[k]);
            if (k == 'worker') {
                modalQueue.push(() => $ctrl.handlers.position.worker.openWorkerAssignment($ctrl.uiState.stored.entityId));
            } else modalQueue.push(() => $ctrl.handlers.position.payComponent.openPayComponentAssignment(k.toUpperCase(), $ctrl.uiState.stored.entityId));
        }
    }

    if (modalQueue.length > 0) {
        $ctrl.isModalBgVisible = true;
        try {
            for (const openModalStep of modalQueue) {
                await openModalStep();
            }
        } catch (err) {
            console.warn("Modal sequence cancelled or failed:", err);
        } finally {
            $ctrl.isModalBgVisible = false;
        }
    }
}

$ctrl.uiState.assignments.pay_schedule.position.loading = true;
$ctrl.uiState.assignments.pay_schedule.position.displayed = ["Loading..."];

const res = await $ctrl.payrollApiService.get({
    limit: 1000,
    entity: "position",
    query: `select=Id,Department,Title&PayScheduleId_eq=${targetId}`
});

if ($ctrl.uiState.selectedEntity?.Id !== targetId) {
    return;
}

const positions = res.entities ?? res ?? [];

$ctrl.uiState.assignments.pay_schedule.position.original = positions;
$ctrl.uiState.assignments.pay_schedule.position.current = positions;

$ctrl.uiState.assignments.pay_schedule.position.displayed = positions.length > 0
    ? positions.map(p => p.Title)
    : []; 

$ctrl.uiState.assignments.pay_schedule.position.loading = false;

const state = $ctrl.uiState.assignments.position;

$ctrl.uiState.assignments.position.earning.loading = true;
$ctrl.uiState.assignments.position.benefit.loading = true;
state.earning.displayed = ["Loading..."];
state.benefit.displayed = ["Loading..."];

const res = await $ctrl.payrollApiService.get({
    limit: 1000,
    entity: "position_pay_component",
    query: `PositionId_eq=${targetId}`,
    customEntityKey: "positionpaycomponent"
});

const entities = res?.entities ?? res;

if ($ctrl.uiState.selectedEntity?.Id !== targetId) {
    return;
}

const links = entities ?? [];

const earningLinks = [];
const benefitLinks = [];

for (const link of links) {
    if (link.ComponentClass === 'EARNING' && link.EarningId) {
        earningLinks.push(link);
    } else if (link.ComponentClass === 'BENEFIT' && link.BenefitId) {
        benefitLinks.push(link);
    }
}

const [resolvedEarnings, resolvedBenefits] = await Promise.all([
    $ctrl.referenceDataService.resolvers.batchResolveById("earning", earningLinks.map(l => l.EarningId) ?? []),
    $ctrl.referenceDataService.resolvers.batchResolveById("benefit", benefitLinks.map(l => l.BenefitId) ?? [])
]);

// Build lookup maps with string-normalized entity IDs as keys
const earningMap = new Map(
    (resolvedEarnings || [])
        .filter(e => e)
        .map(e => [String(e.Id), e.Name])
);

const benefitMap = new Map(
    (resolvedBenefits || [])
        .filter(b => b)
        .map(b => [String(b.Id), b.Name])
);

// --- Handle Earnings ---
const finalEarnings = earningLinks.map(link => ({
    Id: link.Id,
    Name: earningMap.get(String(link.EarningId)) || `Unknown Earning (${link.EarningId})`,
    EarningId: link.EarningId,
    CustomEmployeeAmount: link.CustomEmployeeAmount,
    _linkId: link.Id
}));

state.earning.current = finalEarnings;
state.earning.original = angular.copy(finalEarnings);
state.earning.displayed = finalEarnings.length > 0
    ? finalEarnings.map(e => e.Name)
    : [];

$ctrl.uiState.assignments.position.earning.loading = false;

// --- Handle Benefits ---
const finalBenefits = benefitLinks.map(link => ({
    Id: link.Id,
    Name: benefitMap.get(String(link.BenefitId)) || `Unknown Benefit (${link.BenefitId})`,
    BenefitId: link.BenefitId,
    CustomEmployeeAmount: link.CustomEmployeeAmount,
    CustomEmployerAmount: link.CustomEmployerAmount,
    _linkId: link.Id
}));

state.benefit.current = finalBenefits;
state.benefit.original = angular.copy(finalBenefits);
state.benefit.displayed = finalBenefits.length > 0
    ? finalBenefits.map(b => b.Name)
    : [];

$ctrl.uiState.assignments.position.benefit.loading = false;

const state = $ctrl.uiState.assignments.position.worker;

$ctrl.uiState.assignments.position.worker.loading = true;
state.displayed = ["Loading..."];

const res = await $ctrl.payrollApiService.get({
    limit: 1000,
    entity: "worker_position",
    query: `PositionId_eq=${targetId}`,
    customEntityKey: "workerposition"
});

if ($ctrl.uiState.selectedEntity?.Id !== targetId) {
    return;
}

const links = res?.entities ?? res ?? [];
const workerIds = links.map(wp => wp.WorkerId);

const resolvedUsers = await $ctrl.referenceDataService.resolvers.batch.resolveUsersByWorkerId(workerIds) ?? [];

// Map population with string-normalized WorkerId keys
const userMap = new Map();
resolvedUsers.forEach(u => {
    if (u) userMap.set(String(u.WorkerId), u);
});

const finalWorkers = links.map(link => {
    // Map lookup with string-normalized WorkerId key
    const user = userMap.get(String(link.WorkerId));

    const name = user ? `${user.FirstName} ${user.LastName}` : "Unknown Worker";
    const email = user ? user.Email : "";

    return {
        Id: link.WorkerId,
        WorkerId: link.WorkerId,
        Name: name,
        Email: email,
        CustomAnnualRate: link.CustomAnnualRate,
        _linkId: link.Id
    };
});

state.current = finalWorkers;
state.original = angular.copy(finalWorkers);

state.displayed = finalWorkers.length > 0
    ? finalWorkers.map(w => w.Name)
    : [];

$ctrl.uiState.assignments.position.worker.loading = false;

const canSwitchTabs = await $ctrl.entityViewService.checkUnsavedChanges(
    $ctrl.uiState.isEditing,
    $ctrl.selectedEntity?.Id,
    null,
    $ctrl.utils,
    $ctrl.uiState.isAdding
);

if (!canSwitchTabs) {
    $ctrl.utils.setSelectedBelliniTabBarTab($ctrl.uiState.currentTab.previousId);
    return;   
} else {
    $ctrl.uiState.currentTab.previousId = selectedTab;
}

$ctrl.baseGridControllerService.resetState($ctrl.uiState);
const selectedTabName = $ctrl.tabItemsMap.get(selectedTab);
$ctrl.uiState.currentTab.name = selectedTabName;
$ctrl.handlers.filter.onReset(false);

$ctrl.uiState.currentFilter.quickSearchPlaceholder = $ctrl.filterService.quickSearchConfig.getSearchPlaceholder(
    selectedTabName,
    $ctrl.tabConfig[selectedTabName].quickSearchDefaultConfig,
    $ctrl.userPreferenceService
);

$ctrl.loaders.loadActiveTab({
    entityType: selectedTabName,
    page: 1
});

const canSwitch = await $ctrl.entityViewService.checkUnsavedChanges(
    $ctrl.uiState.isEditing,
    $ctrl.uiState.selectedEntity?.Id,
    null,
    $ctrl.utils,
    $ctrl.uiState.isAdding
);

if (!canSwitch) {
    $ctrl.tabStore[$ctrl.uiState.currentTab.name].currentPage = $ctrl.tabStore[$ctrl.uiState.currentTab.name].previousPage;
    return;
} else {
    $ctrl.tabStore[$ctrl.uiState.currentTab.name].previousPage = currentPage;
}

$ctrl.loaders.loadActiveTab({page: currentPage})

await $ctrl.baseGridControllerService.handleRowSelection($ctrl, row, {

    uiState: $ctrl.uiState,
    utils: $ctrl.utils,
    referenceService: $ctrl.referenceDataService,
    viewService: $ctrl.entityViewService,
    gridData: $ctrl.tabStore[$ctrl.uiState.currentTab.name]?.data,

    config: {
        exclude: ["CompanyId", "StateId"],
        separators: ["AnnualPayPeriods"],
        mappers: {
            "CalculationMethodId": (val) => (val === 1 ? "FLAT" : "PERCENT"),
            "PayDateOnBD": (val) => (`${val[0] + val.slice(1).toLowerCase()} Business Day`),
        }
    },

    // onFormInit: (entity) => {
    //     $ctrl.initializeForms(entity);
    // }
});

if (row) {
    $ctrl.uiState.isLoadingDetails = true;
    if ($ctrl.uiState.currentTab.name === "pay_schedule") {
        $ctrl.loaders.pay_schedule.loadAssignedPositions(row.Id);
    } else {
        $ctrl.loaders.position.loadPositionPayComponents(row.Id);
        $ctrl.loaders.position.loadAssignedWorkers(row.Id);
    }
    $ctrl.uiState.isLoadingDetails = false;
}

const tableCtrl = angular.element(document.querySelector('bln-table')).isolateScope().$ctrl;

if ($ctrl.uiState.isEditing) {
    $ctrl.utils.resetForm($ctrl.form4);
    $ctrl.utils.resetForm($ctrl.form5);
    $ctrl.uiState.isEditing = false;
    return;
} else {
    $ctrl.uiState.selectedEntity = null;
}

const formKey = $ctrl.tabConfig[$ctrl.uiState.currentTab.name].form;
$ctrl.uiState.isAdding = !$ctrl.uiState.isAdding;
$ctrl.utils.resetForm($ctrl[formKey]);

if ($ctrl.uiState.currentTab.name === "position") {
    const uniqueDepartments = [...new Set($ctrl.tabStore.position.data.map(p => p.Department))];

    $ctrl.departmentMap = uniqueDepartments.map(dept => ({
        label: dept,
        value: dept
    }));
}

tableCtrl.gridApi.selection.clearSelectedRows();

if ($ctrl.uiState.isEditing) {
    $ctrl.utils.resetForm($ctrl.form4);
    $ctrl.utils.resetForm($ctrl.form5);
}

$ctrl.handlers.setInputValues();
$ctrl.uiState.isEditing = true;

if (!$ctrl.uiState.selectedEntity) return;
switch ($ctrl.uiState.currentTab.name) {
    case "pay_schedule":
        useExistingValuesAsInputValues($ctrl.form4);
        $ctrl.form4.payDateOnBd = $ctrl.uiState.selectedEntity?.PayDateOnBD;
        $ctrl.form4.workingDays = $ctrl.convertStringToWorkingDays($ctrl.uiState.selectedEntity?.WorkingDays);
        break;

    case "position":
        useExistingValuesAsInputValues($ctrl.form5);
        break;
}

function useExistingValuesAsInputValues(form) {
    const obj = $ctrl.uiState.selectedEntity;

    for (let key in form) {
        const adjustedKey = key.charAt(0).toUpperCase() + key.slice(1);


        form[key] = obj.hasOwnProperty(adjustedKey) ? obj[adjustedKey] : undefined;
    }
}

$ctrl.uiState.currentFilter.currentFilterString = newValue;

if (newValue.trim()) {
    const quickSearchConfig = $ctrl.tabConfig[$ctrl.uiState.currentTab.name].quickSearchDefaultConfig;

    $ctrl.uiState.currentFilter.advancedFilters = [{
        property: quickSearchConfig.property, 
        operation: quickSearchConfig.operation,
        value: newValue
    }];
} else {
    $ctrl.uiState.currentFilter.advancedFilters = [];
}

$ctrl.loaders.loadActiveTab({
    page: 1
});

const filters = newFilters || [];

$ctrl.uiState.currentFilter.currentFilterString = ""; // Clear quick search
$ctrl.uiState.currentFilter.advancedFilters = filters;
$ctrl.uiState.currentFilter.usingAdvancedFilters = filters.length > 0;

$ctrl.handlers.filter.updateFilterChips();

$ctrl.loaders.loadActiveTab({ page: 1 });

const entityType = $ctrl.uiState.currentTab.name;
const service = $ctrl.tabConfig[entityType].service ?? $ctrl[entityType + "Service"];
const definitions = service?.getFilterDefinitions ? service.getFilterDefinitions() : [];

$ctrl.$modal.open("advanced-filter-modal", {
    resolve: {
        definitions,
        currentFilters: angular.copy($ctrl.uiState.currentFilter.advancedFilters),
        referenceData: {
            currencyMap: $ctrl.currencyMap,
            countryMap: $ctrl.countryMap,
            stateMap: Object.values($ctrl.stateMap).flat(),
            payScheduleMap: $ctrl.payScheduleMap
        }
    }
}).then(result => {
    if (result.result === "ok") {
        $ctrl.handlers.filter.onAdvancedFilterUpdate(result.resolve.filters);
    }
})

const currentTabName = $ctrl.uiState.currentTab.name;
const service = $ctrl.tabConfig[currentTabName]?.service ?? $ctrl[currentTabName + "Service"];
const definitions = service?.getFilterDefinitions ? service.getFilterDefinitions() : [];

const result = $ctrl.filterService.generateChips(
    $ctrl.uiState.currentFilter.advancedFilters,
    definitions,
    {
        countryMap: $ctrl.countryMap,
        stateMap: Object.values($ctrl.stateMap ?? {}).flat(),
    },
    Object.fromEntries(
        $ctrl.en.modals.advancedFilterModal.dropdowns.FILTER_OPERATION.values
            .map(op => [op.value, op.label])
    )
);

$ctrl.uiState.currentFilter.chips = result.strings;
$ctrl.uiState.currentFilter.chipMap = result.map;

if (!Array.isArray(remainingStrings)) return;

const newFilterState = remainingStrings
    .map(label => $ctrl.uiState.currentFilter.chipMap[label])
    .filter(obj => obj !== undefined);

$ctrl.handlers.filter.onAdvancedFilterUpdate(newFilterState);

$ctrl.uiState.currentFilter.currentFilterString = "";
$ctrl.uiState.currentFilter.advancedFilters = [];
$ctrl.uiState.currentFilter.usingAdvancedFilters = false;

$ctrl.handlers.filter.updateFilterChips();

if (reload) {
    $ctrl.loaders.loadActiveTab({ page: 1 });
}

try {
    const assignedItems = $ctrl.uiState.assignments.pay_schedule.position.current.map(ap => ({
        Id: ap.Id,
        Department: ap.Department,
        Title: ap.Title
    })) ?? [];

    const entity = "position";
    const baseParams = [`CompanyId=${$ctrl.globalSelectedCompany.companyId}`];

    const preloadParams = [...baseParams];
    if (assignedItems.length > 0) {
        preloadParams.push(`Id_notin=${assignedItems.map(ap => ap.Id).join(",")}`);
    }

    const res = await $ctrl.payrollApiService.get({
        entity: entity,
        query: preloadParams.join('&')
    });

    const unassignedItems = (res.entities ?? res).map(p => ({
        Id: p.Id,
        Department: p.Department,
        Title: p.Title
    }));

    const columns = [
        { name: "Department", valueKey: "Department", enableEditing: false },
        { name: "Title", valueKey: "Title", enableEditing: false }
    ];

    return $ctrl.assignmentUtilsService.openAssignmentModal({
        title: `Assign Positions to ${$ctrl.uiState.selectedEntity?.DisplayName ?? ""} Pay Schedule`,
        assigned: { columns, items: assignedItems },
        unassigned: { columns, items: unassignedItems, totalPages: res?.metadata?.pageCount ?? 1 },
        api: {
            entity: entity,
            baseParams: baseParams,
            searchParamKey: "Title_contains",
            searchProperty: "Title",
            exclusionQueryKey: "Id_notin", // Keep pagination/search clean dynamically
            exclusionItemKey: "Id"
        },
        mapEntityFn: p => ({ Id: p.Id, Department: p.Department, Title: p.Title }),
        onApply: (appliedItems) => {
            $ctrl.handlers.pay_schedule.position.savePositionAssignments(appliedItems, payScheduleId);
        }
    });
} catch (e) {
    console.error("Error loading Positions: ", e);
}

if (!finalAssignedPositions) return;

$ctrl.uiState.isUpdating = true;
$ctrl.uiState.assignments.pay_schedule.position.current = finalAssignedPositions;

Promise.all([
    $ctrl.handlers.pay_schedule.position.removeAssignedPositionsFromPaySchedule(),
    $ctrl.handlers.pay_schedule.position.assignPositionsToPaySchedule(payScheduleId)
])
    .then(() => {
        $ctrl.loaders.pay_schedule.loadAssignedPositions(payScheduleId);
    })
    .catch((reason) => {
        $ctrl.utils.toast(
            reason?.data?.message ?? "The synchronization process failed.",
            reason?.data?.result ?? "ERROR"
        );
    })
    .finally(() => {
        $ctrl.uiState.isUpdating = false;
    });

const newPositions = $ctrl.uiState.assignments.pay_schedule.position.current.filter(
    item1 => !$ctrl.uiState.assignments.pay_schedule.position.original.some(item2 => item2.Id === item1.Id)
);

if (newPositions.length === 0) {
    return Promise.resolve(); // Return resolved promise if no new positions to assign
}

return $ctrl.payrollAppApi.lonti_app_payroll_service_pay_schedule_AssignPositionsToPaySchedule(
    { payScheduleId: payScheduleId ?? $ctrl.uiState.selectedEntity.Id },
    { "Id": newPositions.map(position => position.Id) },
    { headers: $ctrl.authCookies.setHeaders() }
).then(result => {
    $ctrl.utils.toast(`Successfully assigned positions to ${$ctrl.uiState.selectedEntity?.DisplayName ?? "Position"}`, result.data.result);
    return result;
}).catch(reason => {
    console.error(reason);
    throw reason; // Ensure the promise rejects on failure
});

$ctrl.isDeletingPositions = true;
const positionsToDelete = $ctrl.uiState.assignments.pay_schedule.position.original.filter(originalPosition => {
    return !$ctrl.uiState.assignments.pay_schedule.position.current || !$ctrl.uiState.assignments.pay_schedule.position.current.some(position => position.Id === originalPosition.Id);
});

if (positionsToDelete.length === 0) {
    $ctrl.isDeletingPositions = false;
    return Promise.resolve(); // Return resolved promise if no positions to delete
}

return $ctrl.payrollAppApi.lonti_app_payroll_service_pay_schedule_UnassignPositionsFromPaySchedule(
    {},
    { Id: positionsToDelete.map(position => position.Id) },
    { headers: $ctrl.authCookies.setHeaders() }
).then(() => {
}).catch(reason => {
    $ctrl.utils.toast(reason?.data?.message, reason?.data?.result);
    throw reason; // Ensure the promise rejects on failure
}).finally(() => {
    $ctrl.isDeletingPositions = false;
});

const assignedItems = $ctrl.uiState.assignments.position.worker.current.map(w => ({
    Id: w.Id,
    WorkerId: w.WorkerId,
    Name: w.Name,
    Email: w.Email,
    CustomAnnualRate: w.CustomAnnualRate,
    _linkId: w._linkId
}));

const initialAssignedIds = assignedItems.map(a => a.WorkerId) ?? [];

// 1. Fetch Company Workers to enforce data scoping
let companyWorkerIds = [];
try {
    companyWorkerIds = await $ctrl.workerService.getCompanyWorkerIds();
} catch (err) {
    console.error("Failed to fetch company worker IDs for scoping:", err);
}

const workerIdFilter = companyWorkerIds.length > 0 ? companyWorkerIds.join(",") : "-1";
const baseParams = [`WorkerId_in=${workerIdFilter}`];

// 2. Build optimized parameters to fetch active positions elsewhere
const workerPositionQueryParams = [
    "select=WorkerId,PositionId",
    `WorkerId_in=${workerIdFilter}`
];

if (initialAssignedIds.length > 0) {
    workerPositionQueryParams.push(`WorkerId_notin=${initialAssignedIds.join(',')}`);
}

try {
    const assignmentRes = await $ctrl.payrollApiService.get({
        entity: "worker_position",
        limit: 1000,
        query: workerPositionQueryParams.join('&'),
        customEntityKey: "workerposition"
    });

    const otherAssignments = assignmentRes.entities ?? assignmentRes ?? [];
    const staticBusyElsewhereIds = Array.isArray(otherAssignments) ? otherAssignments.map(o => o.WorkerId) : [];

    // 3. Compile the initial exclusion list for the unassigned payload
    const totalInitialExclusions = [...initialAssignedIds, ...staticBusyElsewhereIds];
    let preloadQueryParams = [...baseParams];

    if (totalInitialExclusions.length > 0) {
        preloadQueryParams.push(`WorkerId_notin=${totalInitialExclusions.join(",")}`);
    }

    const userRes = await $ctrl.payrollApiService.get({
        entity: "user",
        query: preloadQueryParams.join("&")
    });

    const users = userRes.entities ?? userRes ?? [];
    const unassignedItems = users.map(u => ({
        Id: u.WorkerId,
        WorkerId: u.WorkerId,
        Name: `${u.FirstName} ${u.LastName}`,
        Email: u.Email
    }));

    // 4. Fire up the dynamic modal utility
    return $ctrl.assignmentUtilsService.openAssignmentModal({
        title: `Assign Workers to ${$ctrl.uiState.selectedEntity?.Title ?? "Position"}`,
        assigned: {
            columns: [
                { name: "Name", valueKey: "Name", enableEditing: false },
                { name: "Custom Annual Rate", valueKey: "CustomAnnualRate", enableEditing: true, type: "number" }
            ],
            items: assignedItems
        },
        unassigned: {
            columns: [{ name: "Name", valueKey: "Name", enableEditing: false }],
            items: unassignedItems,
            totalPages: userRes.metadata?.pageCount ?? 1
        },
        api: {
            entity: "user",
            baseParams: baseParams,
            searchParamKey: "FirstName_contains",
            searchProperty: "Name",
            searchPlaceholder: "Search by: contains FirstName",
            exclusionQueryKey: "WorkerId_notin",
            exclusionItemKey: "WorkerId",
            staticExclusions: staticBusyElsewhereIds
        },
        mapEntityFn: u => ({
            Id: u.WorkerId,
            WorkerId: u.WorkerId,
            Name: `${u.FirstName} ${u.LastName}`,
            Email: u.Email
        }),
        onApply: (appliedItems) => {
            $ctrl.handlers.position.worker.saveWorkerAssignments(appliedItems, positionId);
        }
    });

} catch (err) {
    console.warn("Skipping unassigned preload", err);
}

if (!finalWorkerList) return;

$ctrl.isSyncing = true;
const originalList = $ctrl.uiState.assignments.position.worker.original || [];

$ctrl.workerPositionAssignmentService.syncAssignments(
    $ctrl.payrollApiService,
    finalWorkerList,
    originalList,
    positionId
)
    .then(() => {
        $ctrl.loaders.position.loadAssignedWorkers(positionId);
    })
    .catch((err) => {
        console.error("Sync failed", err);
        $ctrl.utils.toast(err.message || "Failed to save assignments", "ERROR");
    })
    .finally(() => {
        $ctrl.isSyncing = false;
    });

const isEarning = componentType === 'EARNING';
const stateKey = isEarning ? 'earning' : 'benefit';
const entityName = isEarning ? 'earning' : 'benefit';
const idKey = isEarning ? 'EarningId' : 'BenefitId';
const title = isEarning ? 'Earnings' : 'Benefits';

const currentList = $ctrl.uiState.assignments.position[stateKey].current || [];
const assignedItems = currentList.map(item => ({
    Id: item[idKey],
    _linkId: item.Id,
    Name: item.Name,
    [idKey]: item[idKey],
    CustomEmployeeAmount: item.CustomEmployeeAmount,
    ...(!isEarning && { CustomEmployerAmount: item.CustomEmployerAmount })
}));

const alreadyAssignedIds = assignedItems.map(x => x[idKey]);

try {
    let baseParams = [`CompanyId=${$ctrl.globalSelectedCompany.companyId}`, `Active=1`];
    let preloadQuery = [...baseParams];
    if (alreadyAssignedIds.length > 0) {
        preloadQuery.push(`Id_notin=${alreadyAssignedIds.join(",")}`);
    }

    const res = await $ctrl.payrollApiService.get({
        entity: entityName,
        query: preloadQuery.join("&")
    });

    const entities = res.entities ?? res ?? [];
    const unassignedItems = entities.map(e => ({
        Id: e.Id,
        Name: e.Name,
        [idKey]: e.Id
    }));

    return $ctrl.assignmentUtilsService.openAssignmentModal({
        title: `Assign ${title} to ${$ctrl.uiState.selectedEntity?.Title ?? "Position"}`,
        assigned: {
            columns: [
                { name: "Name", valueKey: "Name", enableEditing: false },
                { name: "Custom Employee Amount", valueKey: "CustomEmployeeAmount", enableEditing: true, type: "number" },
                ...(!isEarning ? [{ name: "Custom Employer Amount", valueKey: "CustomEmployerAmount", enableEditing: true, type: "number" }] : [])
            ],
            items: assignedItems
        },
        unassigned: {
            columns: [{ name: "Name", valueKey: "Name", enableEditing: false }],
            items: unassignedItems,
            totalPages: res.metadata?.pageCount ?? 1
        },
        api: {
            entity: entityName,
            baseParams: baseParams,
            searchParamKey: "Name_contains",
            searchProperty: "Name",
            exclusionQueryKey: "Id_notin",
            exclusionItemKey: idKey // Uses structural EarningId/BenefitId context live
        },
        mapEntityFn: e => ({
            Id: e.Id,
            Name: e.Name,
            [idKey]: e.Id
        }),
        onApply: (appliedItems) => {
            $ctrl.payComponentAssignmentService.syncPayComponentsByPositionOrWorker(
                $ctrl.payrollApiService,
                'position',
                positionId,
                componentType,
                $ctrl.uiState.assignments.position[stateKey].original,
                appliedItems,
            ).then(() => {
                $ctrl.loaders.position.loadPositionPayComponents(positionId);
            });
        }
    });

} catch (err) {
    console.warn(`Skipping ${entityName} preload due to API error`, err);
}
